function controlLabel(){const label=cabinetOpen?'Close cabinet':watching?'Show controls':'Watch view';$('#watch-view').setAttribute('aria-pressed',String(watching&&!cabinetOpen));$('#watch-view').innerHTML=label+' <kbd>V</kbd>';}
function watchView(on){watching=on;cabinetOpen=false;$('#app').classList.toggle('watching',on);$('#app').classList.remove('cabinet-open');controlLabel();}
