$('#close-dialog').onclick=closeDialog;modal.addEventListener('close',()=>{loadAbort?.abort();districtPicker?.destroy();districtPicker=null;});modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog();}});
function selectJunction(n,{open=false,highlight=open}={}){if(drillSession&&n.id!==drillSession.node.id)exitDrill(false);if(activeTab==='fleet')tab('signals',{reveal:false});selectedCarId=null;view.selectVehicle(null);selected=n;view.select(highlight?n:null);const index=world.junctions.indexOf(n)+1;$('#junction-id').textContent='J–'+String(index).padStart(3,'0');$('#selected-tag').innerHTML=`J–${String(index).padStart(3,'0')} <span>SELECTED</span>`;$('#junction-name').textContent=n.name.split(' / ').map(s=>s.replace(/^North /,'N ').replace(/^West /,'W ')).join(' & ');draft=normalizePlan(plans.get(n.id)||defaultPlan(n),n);mountCabinet($('#cabinet'),n,()=>{sim.requestPedestrian(n);updateCabinet(n,sim.controllers.get(n.id),sim);toast(sim.controllers.get(n.id).plan.control==='signal'?'Pedestrian call registered. Wait for WALK; finish crossing during flashing DON’T WALK.':'Crossing requested. Pedestrians wait for a gap; vehicles yield while people cross.');});renderEditor();renderRoads();renderData();updateCabinet(n,sim.controllers.get(n.id),sim);updatePlayground();if(open){tab('signals');$('.cabinet-details').open=true;$('.cabinet-details').scrollIntoView({block:'start'});}}
function renderEditor(){
 $$('[data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode===draft.mode));
 $('#mode-description').textContent=draft.mode==='fixed'?'Each approach gets a set green interval. Simple, predictable, and ready for coordination.':'Detectors extend green while vehicles keep arriving. An empty approach gaps out; opposing demand starts the maximum timer.';
 $('#phase-controls').innerHTML=selected.groups.map((g,i)=>`<div class="phase-control"><label for="green-${i}"><span><i class="phase-dot">${i+1}</i>${esc(g.name.replace(/^North /,'N ').replace(/^West /,'W '))}</span><strong><span id="green-value-${i}">${draft.greens[i]}</span> s</strong></label><input id="green-${i}" data-phase="${i}" type="range" min="8" max="90" value="${draft.greens[i]}"><small>${draft.mode==='actuated'?'MAXIMUM GREEN / DETECTOR EXTENSION':'GREEN INTERVAL / BOTH DIRECTIONS'}</small></div>`).join('');
 $$('[data-phase]').forEach(input=>input.oninput=()=>{draft.greens[+input.dataset.phase]=+input.value;$(`#green-value-${input.dataset.phase}`).textContent=input.value;renderPhaseBar();});
 $('#detector-settings').hidden=draft.mode!=='actuated';$('#min-green').value=draft.minGreen;$('#passage-gap').value=draft.gap;$('#offset').disabled=draft.mode==='actuated';$('#offset').value=draft.offset;$('#offset-value').textContent=draft.offset;renderMovementEditor();renderPhaseBar();renderControlButtons();
 $('#signals-panel .apply-status').textContent=draft.control!=='signal'?'This junction uses signs or priority rules. Install a signal under Road works.':'Changes take effect after safe clearance.';$('#apply-plan').disabled=draft.control!=='signal';
}
function renderMovementEditor(){
 $('#movement-controls').innerHTML=`<div class="subheading">PROTECTED LEFT TURNS</div>${selected.groups.map((g,i)=>`<label class="movement-toggle"><input type="checkbox" data-protected="${i}" ${draft.protectedLefts[i]?'checked':''}><span>↰ ${esc(g.name.replace(/^North /,'N ').replace(/^West /,'W '))}</span></label>`).join('')}<label class="number-field">Green arrow <input id="left-green" type="number" min="5" max="30" value="${draft.leftGreen}"><span>s</span></label><p class="helper">Enabled: left-turners wait for their arrow; through traffic stays red. Disabled: left turns yield to opposing traffic on the circular green. A turn bay helps a shared lane avoid blocking.</p><div class="subheading section">PEDESTRIAN SERVICE</div><label class="movement-toggle"><input id="ped-service" type="checkbox" ${draft.pedestrian?'checked':''}><span>Exclusive all-crosswalk phase</span></label><label class="number-field">WALK interval <input id="ped-walk" type="number" min="7" max="20" value="${draft.pedWalk}"><span>s</span></label><p class="helper">Flashing DON'T WALK clearance: <strong id="ped-clearance">${pedestrianClearance(selected)} s</strong>, calculated from crossing width at 1.1 m/s plus a buffer. All vehicle movements remain red until everyone has cleared.</p>`;
 $$('[data-protected]').forEach(input=>input.onchange=()=>{draft.protectedLefts[+input.dataset.protected]=input.checked;renderPhaseBar();});$('#left-green').oninput=e=>{draft.leftGreen=+e.target.value;renderPhaseBar();};$('#ped-service').onchange=e=>{draft.pedestrian=e.target.checked;renderPhaseBar();};$('#ped-walk').oninput=e=>{draft.pedWalk=+e.target.value;renderPhaseBar();};
}
function renderPhaseBar(){const program=planProgram(draft,selected),total=program.reduce((s,p)=>s+p.duration,0);$('#cycle-length').textContent=total+' s '+(draft.mode==='actuated'?'maximum':'cycle');$('#phase-bar').innerHTML=program.map(p=>`<span title="${p.kind==='pedestrian'?'Pedestrians':p.kind==='left'?'Protected left':'Through'} / ${p.stage} / ${p.duration} s" class="${p.stage==='yellow'?'yellow':p.stage==='all-red'?'clear':p.kind==='pedestrian'?'ped-phase':p.kind==='left'?'left-phase':''}" style="flex:${p.duration}"></span>`).join('');$('#ped-clearance')&&($('#ped-clearance').textContent=pedestrianClearance(selected)+' s');}

function tab(name,{reveal=true}={}){if(reveal)openCabinet();activeTab=name;$('.quick-tuning').hidden=name!=='signals';$('.inspector-scroll').scrollTop=0;if(selected&&name!=='fleet'){const id='J–'+String(world.junctions.indexOf(selected)+1).padStart(3,'0');$('.right-panel>.panel-heading').firstChild.textContent='FIELD CONTROLLER CABINET ';$('#junction-id').textContent=id;$('.junction-heading small').textContent='SELECTED INTERSECTION';$('#junction-name').textContent=selected.name.split(' / ').map(s=>s.replace(/^North /,'N ').replace(/^West /,'W ')).join(' & ');}for(const t of ['signals','roads','data','fleet','practice'])$(`#${t}-panel`).hidden=t!==name;$$('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===name));$$('[data-tool]').forEach(b=>b.classList.toggle('active',b.dataset.tool===(name==='data'?'inspect':name)));}
$$('[data-tab]').forEach(b=>b.onclick=()=>{tab(b.dataset.tab);if(b.dataset.tab==='fleet')renderFleet();});$$('[data-tool]').forEach(b=>b.onclick=()=>{tab(b.dataset.tool==='inspect'?'data':b.dataset.tool);toast(b.dataset.tool==='inspect'?'Select a marked junction to inspect its controller.':b.dataset.tool==='signals'?'Adjust the green intervals, then apply the signal plan.':b.dataset.tool==='fleet'?'Click a car to inspect its destination and planned route.':'Select an approach to change its lane geometry.');});
$$('[data-mode]').forEach(b=>b.onclick=()=>{if(!draft)return;draft.mode=b.dataset.mode;renderEditor();});
$('#min-green').oninput=e=>draft.minGreen=+e.target.value;$('#passage-gap').oninput=e=>draft.gap=+e.target.value;$('#offset').oninput=e=>{draft.offset=+e.target.value;$('#offset-value').textContent=draft.offset;};
function apply(){if(!selected)return;if(!validatePlan(draft,selected)){toast('Check timing: through green 8–90 s, minimum green 5 s to the shortest maximum, left arrow 5–30 s, WALK 7–20 s.');return;}plans.set(selected.id,structuredClone(draft));sim.controllers.get(selected.id)?.apply(draft);$('#pending-status').textContent='PLAN QUEUED · Waiting for safe all-red clearance';toast('Signal plan queued. The controller will change after clearance.');}
$('#apply-plan').onclick=apply;
function approachBearing(e){const p=e.a===selected.id?e.points[1]:e.points.at(-2),deg=(Math.atan2(p.x-selected.x,selected.z-p.z)*180/Math.PI+360)%360;return ['N','NE','E','SE','S','SW','W','NW'][Math.round(deg/45)%8];}
function renderRoads(){const current=$('#road-select').value;$('#road-select').innerHTML=selected.edges.map(e=>`<option value="${e.id}">${esc(e.name)} · ${approachBearing(e)} approach</option>`).join('');if(selected.edges.some(e=>String(e.id)===current))$('#road-select').value=current;roadSummary();renderControlButtons();}
function renderControlButtons(){$$('[data-control]').forEach(b=>{b.classList.toggle('active',b.dataset.control===draft.control);b.disabled=b.dataset.control===draft.control;});}
function selectedRoad(){return selected.edges.find(e=>String(e.id)===$('#road-select').value)||selected.edges[0];}
function roadSummary(){const e=selectedRoad();$('#road-summary').textContent=`${e.lanes} lane${e.lanes>1?'s':''} per direction · ${e.forward&&e.backward?'two-way':'one-way'}${e.turnBay?' · left-turn bay':''}`;$('#widen-road').disabled=e.lanes>=3;$('#turn-road').disabled=e.turnBay;}
$('#road-select').onchange=roadSummary;
function spend(cost){if(budget<cost){toast('Insufficient works budget. Signal retiming is free.');return false;}budget-=cost;$('#budget').textContent='$'+budget.toLocaleString();$('#budget-fill').style.width=(budget/500)+'%';return true;}
$$('[data-control]').forEach(b=>b.onclick=()=>{const control=b.dataset.control;if(control===draft.control)return;const cost=control==='signal'?15000:2000;if(!spend(cost))return;draft.control=control;plans.set(selected.id,structuredClone(draft));sim.controllers.get(selected.id).apply(draft);if(control==='signal'&&!view.signals.some(s=>s.node===selected.id))view.addSignal(selected);renderEditor();toast(`${control==='signal'?'Traffic signal installation':'All-way stop conversion'} queued after safe clearance. −$${cost.toLocaleString()}`);});
$('#widen-road').onclick=()=>{const e=selectedRoad();if(e.lanes>=3||!spend(10000))return;e.lanes++;view.buildRoads();sim.refreshGeometry();roadSummary();renderPhaseBar();toast('Approach widened. Added one lane in each permitted direction.');};
$('#turn-road').onclick=()=>{const e=selectedRoad();if(e.turnBay||!spend(5000))return;e.turnBay=true;e.lanes=Math.max(2,e.lanes);view.buildRoads();sim.refreshGeometry();roadSummary();renderPhaseBar();toast('Left-turn bay installed. Turning vehicles use the inner lane.');};
function renderData(){const observed=selected.edges.filter(e=>e.observation);const rows=[...new Map(observed.map(e=>[e.observation.recordid,e.observation])).values()];$('#data-details').innerHTML=`<div class="data-row"><small>STREET GEOMETRY</small><strong>OpenStreetMap · ODbL</strong><p>${esc(world.raw.acquired||'Loaded this session')} · ${world.edges.length} links · ${world.buildings.length} buildings<br>Control: ${esc(selected.controlSource)}. Complex junctions within 23 m are simplified.</p></div><div class="data-row"><small>DEMAND BASIS / THIS JUNCTION</small><strong>${rows.length?'Observed daily count + modeled trips':'Estimated demand'}</strong><p>${rows.length?'Nearby same-road daily counts calibrate arrival estimates at matched boundary gateways. They do not measure turning demand at this junction.':'No matching count within 450 m. Road class and mapped land use supply a transparent demand estimate.'}</p></div>${rows.slice(0,4).map(o=>`<div class="data-row"><small>${esc(o.roadname)} · ${esc(o.direction||'DIRECTION UNSPECIFIED')}</small><strong>${(+o.vehiclecount).toLocaleString()} vehicles / day</strong><p>Count date: ${esc(o.timestamp?.slice(0,10)||'unknown')}<br>${esc(o.fromsegment||'Imported segment')} → ${esc(o.tosegment||'')}<br>${esc(o._source||'City of Chicago · camera-derived daily count')}</p></div>`).join('')}`;}
function updateUI(){if(!sim)return;updatePlayground();if(activeTab==='fleet')renderFleet();const m=sim.metrics(),preset=TRAFFIC_PRESETS.find(p=>p.demand===density);$('#traffic-preset').textContent=(preset?.label||'Custom')+' · '+density.toFixed(2)+'×';$('#live-fleet-count').textContent=`${m.active} cars · ${m.turning} turning · ${sim.cars.filter(c=>c.speed<.7).length} waiting`;$('#metric-delay').textContent=m.delay.toFixed(1);$('#metric-queue').textContent=m.queue;$('#metric-throughput').textContent=m.completed;$('#metric-speed').textContent=m.speed.toFixed(0);const h=period==='am'?8:period==='midday'?12:17;const seconds=Math.floor(sim.time),hh=(h+Math.floor(seconds/3600))%24;$('#sim-time').textContent=`${String(hh).padStart(2,'0')}:${String(Math.floor(seconds/60)%60).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`;
 const hist=sim.history.slice(-30);if(hist.length){let max=Math.max(5,...hist.map(h=>h.delay));$('#delay-spark').setAttribute('d',hist.map((h,i)=>`${i?'L':'M'}${i/(hist.length-1||1)*90} ${24-h.delay/max*20}`).join(''));}
 if(selected&&sim.controllers.has(selected.id)){let c=sim.controllers.get(selected.id);if(activeTab!=='fleet')$('#control-status').textContent=c.plan.control!=='signal'?(c.plan.control==='stop'?'ALL-WAY STOP':'PRIORITY / APPROACH SIGNS'):`${c.plan.mode==='actuated'?'ACTUATED':'FIXED'} / ${c.kind==='pedestrian'?'PEDESTRIANS':c.kind==='left'?'LEFT ARROW':'THROUGH'} / ${c.stage.toUpperCase()}`;if(activeTab!=='fleet')$('#junction-queue').textContent=sim.queueAt(selected.id)+' queued';updateCabinet(selected,c,sim);if(!c.pending&&plans.has(selected.id))$('#pending-status').textContent=`PLAN ACTIVE · ${c.lastReason.toUpperCase()}`;}
}
function syncPlayback(){
 $('#pause').textContent=paused?'▶':'Ⅱ';$('#pause').title=paused?'Resume simulation':'Pause simulation';
 $$('.speeds [data-speed]').forEach(b=>b.classList.toggle('active',+b.dataset.speed===speed));
 $('.statusbar>span').innerHTML=`<i class="led"></i> ${drillSession?'JUNCTION DRILL':paused?'SIMULATION PAUSED':'SIMULATION RUNNING'} <span class="status-sep">│</span> <span id="data-status">${drillSession?'SYNTHETIC TEST WAVE':world.edges.some(e=>e.observation)?'OBSERVED COUNTS + MODELED TRIPS':'OSM GEOMETRY + MODELED TRIPS'}</span>`;
}
function updatePlayground(){
 if(!selected||!sim)return;
 $('#dock-junction').textContent=selected.name.split(' / ').map(name=>name.replace(/^North /,'N ').replace(/^West /,'W ')).join(' / ');
 if(!drillSession){const available=new Set(drillConnections(selected).map(c=>c.movement));for(const option of $('#drill-mix').options)option.disabled=option.value!=='mixed'&&!available.has(option.value);if($('#drill-mix').selectedOptions[0]?.disabled)$('#drill-mix').value='mixed';$('#start-drill').disabled=!available.size;}const c=sim.controllers.get(selected.id);if(!c)return;
 const group=c.node.groups[c.phase],duration=c.program[c.programIndex]?.duration||0,remaining=Math.max(0,Math.ceil(duration-c.elapsed));
 $('#live-phase').textContent=c.plan.control==='signal'?(c.kind==='pedestrian'?(c.stage==='walk'?'WALK · Vehicles stopped':c.stage==='ped-clear'?'CROSSING CLEARANCE':'ALL RED · Crossing clearance'):c.stage==='all-red'?'ALL RED · Clearing intersection':`${c.kind==='left'?'↰ LEFT ARROWS':'↑ THROUGH / ↱ RIGHT'} · ${group?.name.replace(/^North /,'N ').replace(/^West /,'W ')||''} · ${c.stage.toUpperCase()} ${remaining}s`):c.plan.control==='stop'?'ALL-WAY STOP · Stop, then take a safe gap':'PRIORITY JUNCTION · Side streets yield';
 $('#movement-board').innerHTML=approachReadings(sim,selected).map(a=>`<div class="movement-row"><b>${a.bearing}</b><span class="movement-road" title="${esc(a.edge.name)}">${esc(a.edge.name.replace(/^North /,'N ').replace(/^West /,'W '))}</span>${a.movements.map(m=>`<span class="movement-lamp ${m.state} ${m.available?'':'unavailable'}" title="${esc(m.movement+' · '+m.reason)}" aria-label="${esc(a.bearing+' '+m.movement+': '+(m.available?m.state:'unavailable'))}">${MOVEMENT_SYMBOLS[m.movement]}</span>`).join('')}<span class="movement-wait">${a.waiting}<small>WAIT</small></span></div>`).join('');
 $('#quick-green').disabled=c.plan.control!=='signal'||c.phase<0;$('#quick-balanced').disabled=c.plan.control!=='signal';
 if(!drillSession)return;
 const r=drillResult(sim),session=drillSession;$('#drill-cleared').textContent=`${r.cleared} / ${r.total}`;$('#drill-clock').textContent=`${Math.floor(r.remaining/60)}:${String(Math.floor(r.remaining%60)).padStart(2,'0')}`;$('#drill-progress').style.width=`${r.cleared/r.total*100}%`;
 if(r.finished&&!session.result){session.result={...r,time:sim.time};const previous=drillScores.get(session.key);session.comparison=previous?`${r.cleared-previous.cleared>=0?'+':''}${r.cleared-previous.cleared} cars cleared · ${Math.abs(previous.delay-r.delay).toFixed(1)}s ${r.delay<=previous.delay?'less':'more'} delay vs last wave.`:'Retune the cabinet and replay this wave to compare.';drillScores.set(session.key,session.result);paused=true;syncPlayback();}
 $('#drill-score').classList.toggle('finished',r.finished);$('#start-drill').textContent=drillSession?'↻ Replay traffic wave':'▶ Send traffic wave';
 $('#drill-message').textContent=session.result?`${session.result.medal==='gold'?'★ GOLD · Every car cleared in 2 minutes.':session.result.medal==='silver'?'◆ SILVER · At least 80% cleared.':'↻ KEEP TUNING · Aim to clear 80%.'} ${session.comparison}`:`${r.waiting} waiting · ${sim.pendingTrips.length} at entry · Goal ${Math.ceil(r.total*.8)} cleared. Gold: all cars in 2:00.`;
}
function startDrill(){
 if(!selected)return;
 if(!validatePlan(draft,selected)){toast('Check the timing program before starting a wave.');return;}
 const node=selected,count=+$('#drill-count').value,mix=$('#drill-mix').value;
 try{
  const proposed=new Map(plans);proposed.set(node.id,structuredClone(draft));const next=createJunctionDrill(world,proposed,node,{count,mix});
  const saved=drillSession?.saved||{sim,paused,speed};plans.set(node.id,structuredClone(draft));
  drillSession={node,saved,key:`${node.id}/${count}/${mix}`,result:null};sim=next;paused=false;speed=1;accumulator=0;selectedCarId=null;view.selectVehicle(null);tab('practice');view.focusJunction(node);$('#map-shell').classList.add('drill-active');$('#drill-score').hidden=false;$('#dock-hint').hidden=true;$('#drill-count').disabled=$('#drill-mix').disabled=true;syncPlayback();updateUI();
  toast(`${count}-car practice wave dispatched. Retune signals, then replay the same traffic.`);
 }catch(e){toast(e.message);}
}
function exitDrill(notify=true){
 if(!drillSession)return;
 const saved=drillSession.saved;drillSession=null;sim=saved.sim;paused=saved.paused;speed=saved.speed;accumulator=0;
 for(const [id,plan]of plans){const ctl=sim.controllers.get(id);if(ctl&&JSON.stringify(ctl.plan)!==JSON.stringify(plan))ctl.apply(plan);}
 sim.refreshGeometry();selectedCarId=null;view.selectVehicle(null);$('#map-shell').classList.remove('drill-active');$('#drill-score').hidden=true;$('#dock-hint').hidden=false;$('#drill-count').disabled=$('#drill-mix').disabled=false;$('#start-drill').textContent='▶ Send traffic wave';syncPlayback();if(notify){updateUI();toast('Live district restored. Your road works and signal edits are retained.');}
}
$('#open-program').onclick=()=>{const details=$('.timing-details');details.open=true;details.scrollIntoView({block:'start',behavior:'smooth'});};
$('#start-drill').onclick=startDrill;$('#exit-drill').onclick=()=>exitDrill();$('#focus-junction').onclick=selectNearest;
$('#traffic-lens').onclick=()=>{const on=!view.vehicleCues.enabled;view.vehicleCues.enabled=on;$('#traffic-lens').setAttribute('aria-pressed',String(on));$('#traffic-lens strong').textContent=on?'ON':'OFF';};
$('#quick-green').onclick=()=>{const ctl=sim.controllers.get(selected.id),phase=Math.max(0,ctl.phase);const added=Math.min(5,90-draft.greens[phase]);if(!added){toast('This approach already has the maximum 90-second through green.');return;}draft.greens[phase]+=added;renderEditor();apply();toast(`Added ${added} seconds to ${selected.groups[phase].name}. Replay the wave to compare.`);};
$('#quick-balanced').onclick=()=>{draft.greens=draft.greens.map(()=>25);draft.minGreen=Math.min(draft.minGreen,25);renderEditor();apply();toast('Through stages balanced at 25 seconds. Replay the wave to compare.');};

function selectVehicle(car){if(!car)return;selectedCarId=car.id;view.selectVehicle(car);tab('fleet');renderFleet();}
function renderFleet(){
 if(!sim)return;const current=sim.cars.find(c=>c.id===selectedCarId)||view.visibleCars.find(c=>c.turn&&c.turn.movement!=='through')||view.visibleCars.find(c=>c.speed>2)||sim.cars[0],options=sim.cars.slice(0,70);if(current&&!options.includes(current))options.unshift(current);const signature=options.map(c=>c.id).join(',');if($('#vehicle-select').dataset.signature!==signature){$('#vehicle-select').dataset.signature=signature;$('#vehicle-select').innerHTML=options.length?options.map(c=>`<option value="${c.id}">V–${String(c.id).padStart(4,'0')} → ${esc(c.trip?.to.name||'District boundary')}</option>`).join(''):'<option>No vehicles active</option>';if(current)$('#vehicle-select').value=String(current.id);}
 if(current)$('#vehicle-select').value=String(current.id);const c=current||options[0];if(c){$('.right-panel>.panel-heading').firstChild.textContent='VEHICLE DISPATCH ';$('#junction-id').textContent='V–'+String(c.id).padStart(4,'0');$('.junction-heading small').textContent='ASSIGNED DESTINATION';$('#junction-name').textContent=c.trip?.to.name||'District boundary';$('#control-status').textContent=c.turn?(c.turn.movement==='through'?'CROSSING JUNCTION':c.turn.movement.toUpperCase()+' TURN'):c.laneChange?'CHANGING LANE':c.speed<.6?'WAITING FOR RIGHT-OF-WAY':'DRIVING';$('#junction-queue').textContent=(c.speed*3.6).toFixed(0)+' km/h';}if(c&&selectedCarId!==c.id){selectedCarId=c.id;view.selectVehicle(c);}const m=sim.metrics();$('#fleet-summary').textContent=`${m.active} on road · ${sim.pendingTrips.length} awaiting a safe entry · ${m.turning} turning · ${m.arrivalRate.toFixed(0)} requested / hour`;
 $('#vehicle-details').innerHTML=c?`<div class="trip-purpose">${esc(c.trip?.purpose||'District trip')} <strong>V–${String(c.id).padStart(4,'0')}</strong></div><div class="trip-endpoint"><small>FROM</small><strong>${esc(c.trip?.from.name||'Street access')}</strong><span>${esc(c.trip?.from.kind||'modeled origin')}</span></div><div class="trip-endpoint destination-endpoint"><small>DESTINATION</small><strong>${esc(c.trip?.to.name||'District boundary')}</strong><span>${esc(c.trip?.to.kind||'modeled destination')} · ${remainingDistance(c).toFixed(0)} m remaining</span></div><div class="vehicle-readings"><span>${(c.speed*3.6).toFixed(0)} <small>km/h</small></span><span>${c.turn?(c.turn.movement==='through'?'Crossing junction':c.turn.movement+' turn'):c.laneChange?'Changing lane':c.speed<.6?'Waiting':'Driving'}</span><span>Lane ${c.lane+1}</span></div><p class="helper">${esc(c.trip?.demandBasis||'Modeled route')}<br>${esc(c.path[c.index].edge.name)} · ${c.path.length} road links</p>`:'<p class="helper">Waiting for incoming traffic. Every generated car has a destination before it enters the road.</p>';
 const key=`${world.center.lat}/${world.center.lon}/${sim.period}/${density}/${Math.floor(sim.generated/20)}`;if($('#arrival-streams').dataset.key!==key){$('#arrival-streams').dataset.key=key;$('#arrival-streams').innerHTML=sim.tripDemand.summary().slice(0,12).map(s=>`<div class="arrival-stream"><span>${esc(s.name)}</span><strong>${(s.rate*density).toFixed(0)} / h</strong><small>${esc(s.basis)}</small></div>`).join('');}
}
