function parseCSV(text){const lines=text.replace(/^\uFEFF/,'').trim().split(/\r?\n/);const split=s=>s.match(/("(?:[^"]|"")*"|[^,]*)(,|$)/g)?.filter(s=>s!=='').map(s=>s.replace(/,$/,'').replace(/^"|"$/g,'').replaceAll('""','"'))||[];const heads=split(lines.shift()).map(s=>s.trim().toLowerCase());return lines.map(l=>Object.fromEntries(split(l).map((s,i)=>[heads[i],s])));}
$('#counts-upload').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>2000000)throw Error('Use a CSV smaller than 2 MB.');const rows=parseCSV(await file.text()).filter(r=>r.roadname&&+r.vehiclecount>0&&Number.isFinite(+r.midpointlat)&&Number.isFinite(+r.midpointlon));if(!rows.length)throw Error('No valid rows. Required: roadname, vehiclecount, midpointlat, midpointlon.');counts=rows.map((r,i)=>({...r,_source:'User-imported traffic count · not independently verified',recordid:`import-${i}`,segmentid:`import-${r.roadname}-${r.direction}`}));const oldPlans=new Map(plans),oldBudget=budget,roads=world.edges.map(e=>({id:e.id,lanes:e.lanes,turnBay:e.turnBay}));loadArea(world.raw,world.center,counts,areaName);plans=oldPlans;budget=oldBudget;for(const r of roads){const edge=world.edges.find(e=>e.id===r.id);if(edge){edge.lanes=r.lanes;edge.turnBay=r.turnBay;}}view.buildRoads();spend(0);resetSim();selectJunction(selected);toast('Imported traffic counts. Demand recalibrated; your works and plans are retained.');}catch(e){toast(e.message);}};
